export interface TimelineEvent {
  kind: 'user_message' | 'assistant_text' | 'tool_use' | 'tool_result';
  timestamp: number;
  duration: number;
  content: string;
  toolName?: string;
  caption?: string;
}

export interface CastHeader {
  version: 2;
  width: number;
  height: number;
  timestamp: number;
  title: string;
}

export type CastFrame = [number, string, string];

import { TimelineEvent } from './types.js';

export function parseLog(jsonl: string): TimelineEvent[] {
  const lines = jsonl.split('\n').filter(Boolean);
  const events: TimelineEvent[] = [];
  let baseTime = 0;

  for (const line of lines) {
    const entry = JSON.parse(line);
    if (!entry.message) continue;
    const ts = new Date(entry.timestamp).getTime();
    if (!baseTime) baseTime = ts;

    const { role, content } = entry.message;
    const blocks = typeof content === 'string'
      ? [{ type: 'text', text: content }]
      : content;

    for (const block of blocks) {
      if (block.type === 'text') {
        events.push({
          kind: role === 'user' ? 'user_message' : 'assistant_text',
          timestamp: ts - baseTime,
          duration: 0,
          content: block.text,
        });
      } else if (block.type === 'tool_use') {
        events.push({
          kind: 'tool_use',
          timestamp: ts - baseTime,
          duration: 0,
          content: JSON.stringify(block.input),
          toolName: block.name,
          caption: `${block.name}: ${Object.values(block.input)[0]}`,
        });
      } else if (block.type === 'tool_result') {
        events.push({
          kind: 'tool_result',
          timestamp: ts - baseTime,
          duration: 0,
          content: typeof block.content === 'string'
            ? block.content : JSON.stringify(block.content),
        });
      }
    }
  }
  return events;
}

import { TimelineEvent, CastHeader, CastFrame } from './types.js';

const PROMPT = '\x1b[1;34m❯\x1b[0m ';
const TOOL_COLOR = '\x1b[38;5;244m';
const RESET = '\x1b[0m';

export function render(events: TimelineEvent[], width = 120, height = 40): string {
  const header: CastHeader = { version: 2, width, height, timestamp: Math.floor(Date.now() / 1000), title: 'Claude Code Session' };
  const frames: CastFrame[] = [];
  let time = 0;

  for (const event of events) {
    time = event.timestamp / 1000;
    switch (event.kind) {
      case 'user_message':
        frames.push([time, 'o', PROMPT + event.content + '\r\n']);
        break;
      case 'assistant_text':
        frames.push([time, 'o', event.content + '\r\n']);
        break;
      case 'tool_use':
        frames.push([time, 'o', TOOL_COLOR + `[${event.toolName}] ${event.caption}` + RESET + '\r\n']);
        break;
      case 'tool_result':
        frames.push([time, 'o', TOOL_COLOR + event.content + RESET + '\r\n']);
        break;
    }
  }

  return [JSON.stringify(header), ...frames.map(f => JSON.stringify(f))].join('\n') + '\n';
}
